#include "PatientSpecificCalibrationProfile.h"
namespace dnxr { CalibrationProfileDecision PatientSpecificCalibrationProfileVerifier::verify(const PatientSpecificCalibrationProfile& p, std::int64_t now) const { CalibrationProfileDecision d; if(p.patientPseudonym.empty()) d.blockers.push_back("patient_pseudonym_missing"); if(p.profileId.empty()) d.blockers.push_back("profile_id_missing"); if(p.deviceId.empty()) d.blockers.push_back("device_id_missing"); if(p.hash.size()<16U) d.blockers.push_back("calibration_hash_invalid"); if(p.signature.size()<16U) d.blockers.push_back("calibration_signature_invalid"); if(p.expiresAtUnixSeconds<=now) d.blockers.push_back("calibration_expired"); d.valid=d.blockers.empty(); return d; } }
